// ── Word form resolution ─────────────────────────────────────
// Russian has extensive morphology: nouns decline in 6 cases, adjectives agree
// in gender/number/case, and verbs conjugate.

// Noun case ending patterns for stripping (ordered longest-first for greedy match)
const NOUN_ENDINGS: string[] = [
  // Instrumental plural
  'ами', 'ями',
  // Genitive plural
  'ов', 'ев', 'ёв',
  // Prepositional/dative plural
  'ам', 'ям',
  // Prepositional plural
  'ах', 'ях',
  // Genitive/accusative singular feminine & plural
  'ой', 'ей', 'ою', 'ею',
  // Instrumental singular
  'ом', 'ем', 'ём',
  // Dative singular
  'у', 'ю',
  // Prepositional singular
  'е',
  // Genitive singular & nominative plural
  'а', 'я', 'ы', 'и',
];

// Adjective ending mappings: inflected → possible masculine nominative endings
const ADJ_ENDINGS: { suffix: string; bases: string[] }[] = [
  // Instrumental plural (longest first)
  { suffix: 'ыми', bases: ['ый', 'ой'] },
  { suffix: 'ими', bases: ['ий'] },
  // Genitive masculine/neuter
  { suffix: 'ого', bases: ['ый', 'ой'] },
  { suffix: 'его', bases: ['ий'] },
  // Dative masculine/neuter
  { suffix: 'ому', bases: ['ый', 'ой'] },
  { suffix: 'ему', bases: ['ий'] },
  // Feminine
  { suffix: 'ая', bases: ['ый', 'ой'] },
  { suffix: 'яя', bases: ['ий'] },
  // Neuter
  { suffix: 'ое', bases: ['ый', 'ой'] },
  { suffix: 'ее', bases: ['ий'] },
  // Plural nominative/accusative
  { suffix: 'ые', bases: ['ый', 'ой'] },
  { suffix: 'ие', bases: ['ий', 'ой'] },
  // Genitive/prepositional plural
  { suffix: 'ых', bases: ['ый', 'ой'] },
  { suffix: 'их', bases: ['ий'] },
  // Dative plural / instrumental singular masc
  { suffix: 'ым', bases: ['ый', 'ой'] },
  { suffix: 'им', bases: ['ий'] },
  // Prepositional singular masc / feminine oblique
  { suffix: 'ом', bases: ['ый', 'ой'] },
  { suffix: 'ем', bases: ['ий'] },
  { suffix: 'ой', bases: ['ый', 'ой'] },
  { suffix: 'ей', bases: ['ий'] },
];

function cleanWord(word: string): string {
  return word
    .replace(/[.,!?;:"""''«»()—–\-…\d]/g, '')
    .trim()
    .toLowerCase();
}

export function lookupWord(word: string): DictEntry | null {
  const clean = cleanWord(word).trim();
  if (!clean) return null;

  // Direct lookup
  if (dictionary[clean]) return dictionary[clean];

  // Try ё/е variation (ё is often written as е in informal text)
  const withYo = clean.replace(/е/g, 'ё');
  if (withYo !== clean && dictionary[withYo]) return dictionary[withYo];
  const withoutYo = clean.replace(/ё/g, 'е');
  if (withoutYo !== clean && dictionary[withoutYo]) return dictionary[withoutYo];

  // Try verb form resolution via conjugation engine (all candidate infinitives)
  const infCandidates = findInfinitiveCandidates(clean);
  for (const inf of infCandidates) {
    if (dictionary[inf]) return dictionary[inf];
    // Also try ё/е variation on candidates
    const infYo = inf.replace(/е/g, 'ё');
    if (infYo !== inf && dictionary[infYo]) return dictionary[infYo];
    const infNoYo = inf.replace(/ё/g, 'е');
    if (infNoYo !== inf && dictionary[infNoYo]) return dictionary[infNoYo];
  }

  // Try adjective ending stripping
  for (const { suffix, bases } of ADJ_ENDINGS) {
    if (clean.endsWith(suffix) && clean.length > suffix.length + 1) {
      const stem = clean.slice(0, -suffix.length);
      for (const base of bases) {
        const candidate = stem + base;
        if (dictionary[candidate]) return dictionary[candidate];
      }
    }
  }

  // Try noun case ending stripping (longest suffix first for greedy match)
  for (const ending of NOUN_ENDINGS) {
    if (clean.endsWith(ending) && clean.length > ending.length + 1) {
      const stem = clean.slice(0, -ending.length);
      // Try direct stem
      if (dictionary[stem]) return dictionary[stem];
      // Try stem + common nominative endings
      for (const nom of ['', 'а', 'о', 'е', 'ь', 'й', 'я']) {
        const candidate = stem + nom;
        if (dictionary[candidate]) return dictionary[candidate];
      }
    }
  }

  // Try multi-word expressions
  const parts = clean.split(/\s+/);
  if (parts.length > 1) {
    // First try the whole phrase
    const phrase = parts.join(' ');
    if (dictionary[phrase]) return dictionary[phrase];
    // Then try individual words
    for (const part of parts) {
      if (dictionary[part]) return dictionary[part];
    }
  }

  // Try stripping reflexive suffix -ся/-сь
  if (clean.endsWith('ся')) {
    const base = clean.slice(0, -2);
    if (dictionary[base]) return dictionary[base];
    const infRefl = findInfinitive(clean);
    if (infRefl && dictionary[infRefl]) return dictionary[infRefl];
  }
  if (clean.endsWith('сь')) {
    const base = clean.slice(0, -2) + 'ся';
    if (dictionary[base]) return dictionary[base];
  }

  return null;
}

export default dictionary;
